// Vector math helpers
function vec3Add(a, b) { return [a[0]+b[0], a[1]+b[1], a[2]+b[2]]; }
function vec3Sub(a, b) { return [a[0]-b[0], a[1]-b[1], a[2]-b[2]]; }
function vec3Scale(a, s) { return [a[0]*s, a[1]*s, a[2]*s]; }
function vec3Dot(a, b) { return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; }
function vec3Lerp(a, b, t) { return [a[0]+(b[0]-a[0])*t, a[1]+(b[1]-a[1])*t, a[2]+(b[2]-a[2])*t]; }

// Computes world position p(t, theta_book) and converts into TangentFrame local coordinates (u_local, v_local, n_local)
function computeLocal3D(pos3d, posUv, role, frame, flattenT, bookTheta) {
  const origin = frame.origin;
  const uAxis = frame.axis_u;
  const vAxis = frame.axis_v;
  const nAxis = frame.normal;

  const rel3d = vec3Sub(pos3d, origin);
  const p3Local = [vec3Dot(rel3d, uAxis), vec3Dot(rel3d, vAxis), vec3Dot(rel3d, nAxis)];

  const u = posUv[0];
  const v = posUv[1];
  const sheetOffset = 0.08;
  let pFlatLocal;
  if (role === "Binder") {
    pFlatLocal = [u, v, sheetOffset];
  } else {
    const phi = bookTheta * Math.PI;
    const du = u - frame.hinge_u;
    const uRot = frame.hinge_u + du * Math.cos(phi);
    const nRot = -du * Math.sin(phi) - sheetOffset * Math.cos(phi);
    pFlatLocal = [uRot, v, nRot];
  }

  return vec3Lerp(p3Local, pFlatLocal, flattenT);
}

// Projects a TangentFrame local 3D point (u, v, n) onto 2D screen coordinates (sx, sy, depth)
function projectLocalPoint(localPt, width, height) {
  const cy = Math.cos(state.camYaw), sy = Math.sin(state.camYaw);
  const cp = Math.cos(state.camPitch), sp = Math.sin(state.camPitch);

  const x0 = localPt[0], y0 = localPt[1], z0 = localPt[2];
  // Yaw around v-axis (y0)
  const x1 = x0 * cy + z0 * sy;
  const z1 = -x0 * sy + z0 * cy;
  // Pitch around u-axis (x1)
  const y2 = y0 * cp - z1 * sp;
  const z2 = y0 * sp + z1 * cp;

  const sx = width * 0.5 + state.camPanX + x1 * state.camZoom;
  const syScreen = height * 0.5 + state.camPanY - y2 * state.camZoom;
  return [sx, syScreen, z2];
}

function getAtomFillColor(node, meta) {
  if (state.lens === "Interactions") {
    const s = node.interaction_summary;
    if (s.worst_clash_overlap_a > 0.05) return "#f21414";
    if (s.salt_bridge_count > 0) return "#9d14ff";
    if (s.hbond_count > 0) return "#2563eb";
    return node.role === "Binder" ? "#64748b" : "#94a3b8";
  } else if (state.lens === "Chemistry") {
    const r = meta.res_name;
    if (["ALA","VAL","LEU","ILE","MET"].includes(r)) return "#94a3b8";
    if (["PHE","TYR","TRP"].includes(r)) return "#f59e0b";
    if (["SER","THR","ASN","GLN","CYS"].includes(r)) return "#06b6d4";
    if (["LYS","ARG","HIS"].includes(r)) return "#3b82f6";
    if (["ASP","GLU"].includes(r)) return "#ef4444";
    return "#a855f7"; // GLY, PRO
  } else if (state.lens === "ModernCpk") {
    if (meta.element === "N") return "#2563eb";
    if (meta.element === "O") return "#dc2626";
    if (meta.element === "S") return "#d97706";
    return "#475569";
  } else {
    // B-factor / pLDDT
    const b = Math.max(20, Math.min(100, meta.b_factor));
    const norm = (b - 20) / 80;
    if (norm > 0.75) return "#0053d6";
    if (norm > 0.5) return "#65cbf3";
    if (norm > 0.25) return "#ffdb13";
    return "#ff7d45";
  }
}

function getAtomRadiusPx(node) {
  const baseScale = state.camZoom * 0.28;
  if (state.sizeMode === "Uniform") {
    return Math.max(3.5, baseScale * 1.15);
  } else if (state.sizeMode === "Clash") {
    const boost = 1.0 + node.interaction_summary.worst_clash_overlap_a * 2.2;
    return Math.max(3.5, baseScale * boost);
  } else {
    // SqrtSasa
    const s = Math.sqrt(Math.max(1.5, node.buried_sasa_a2));
    return Math.max(3.5, baseScale * (0.65 + 0.25 * s));
  }
}

function updateLegend() {
  const el = document.getElementById("lens-legend");
  const items = {
    Interactions: [
      ["#f21414", "VdW Clash"],
      ["#2563eb", "H-Bond"],
      ["#9d14ff", "Salt Bridge"],
      ["#64748b", "Apolar / Neutral"],
      ["#d97706", "Unsatisfied Buried Polar (Amber Ring)"]
    ],
    Chemistry: [
      ["#94a3b8", "Aliphatic"],
      ["#f59e0b", "Aromatic"],
      ["#06b6d4", "Polar"],
      ["#3b82f6", "Positive"],
      ["#ef4444", "Negative"],
      ["#a855f7", "Gly / Pro"]
    ],
    ModernCpk: [
      ["#475569", "Carbon"],
      ["#2563eb", "Nitrogen"],
      ["#dc2626", "Oxygen"],
      ["#d97706", "Sulfur"]
    ],
    Bfactor: [
      ["#0053d6", "High (>80)"],
      ["#65cbf3", "Med (60-80)"],
      ["#ffdb13", "Low (40-60)"],
      ["#ff7d45", "Very Low (<40)"]
    ]
  }[state.lens] || [];

  el.innerHTML = items.map(([c, lbl]) => `<span><i class="swatch" style="background:${c}"></i>${lbl}</span>`).join("");
}

function render() {
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  if (canvas.width !== Math.round(rect.width * dpr) || canvas.height !== Math.round(rect.height * dpr)) {
    canvas.width = Math.round(rect.width * dpr);
    canvas.height = Math.round(rect.height * dpr);
  }
  ctx.save();
  ctx.scale(dpr, dpr);
  const W = rect.width, H = rect.height;

  ctx.fillStyle = "#f8fafc";
  ctx.fillRect(0, 0, W, H);

  const ds = currentDataset();
  const map = ds.map;
  const frame = map.frame;

  // Draw subtle coordinate grid on tangent plane
  ctx.strokeStyle = "#e2e8f0";
  ctx.lineWidth = 1;
  for (let g = -40; g <= 40; g += 5) {
    const p1 = projectLocalPoint([g, -40, 0], W, H);
    const p2 = projectLocalPoint([g, 40, 0], W, H);
    ctx.beginPath(); ctx.moveTo(p1[0], p1[1]); ctx.lineTo(p2[0], p2[1]); ctx.stroke();
    const q1 = projectLocalPoint([-40, g, 0], W, H);
    const q2 = projectLocalPoint([40, g, 0], W, H);
    ctx.beginPath(); ctx.moveTo(q1[0], q1[1]); ctx.lineTo(q2[0], q2[1]); ctx.stroke();
  }

  // Draw Open-Book Hinge axis line when bookTheta > 0.01
  if (state.bookTheta > 0.01 && state.flattenT > 0.1) {
    const h1 = projectLocalPoint([frame.hinge_u, -28, 0], W, H);
    const h2 = projectLocalPoint([frame.hinge_u, 28, 0], W, H);
    ctx.save();
    ctx.strokeStyle = "#64748b";
    ctx.lineWidth = 1.5;
    ctx.setLineDash([6, 5]);
    ctx.beginPath();
    ctx.moveTo(h1[0], h1[1]);
    ctx.lineTo(h2[0], h2[1]);
    ctx.stroke();
    ctx.fillStyle = "#475569";
    ctx.font = "600 11px Inter, sans-serif";
    ctx.fillText("◀ TARGET (Unfolded Page)   |   BOOK HINGE   |   BINDER (Mutable) ▶", h1[0] - 165, Math.min(h1[1], h2[1]) - 8);
    ctx.restore();
  }

  // 1. Draw 3D C-alpha backbone trace (fades as flattenT -> 1.0, or visible at 25% when checked)
  if (state.showBackbone && state.flattenT < 0.98) {
    const bbAlpha = (1.0 - state.flattenT * 0.85);
    for (const bb of ds.backbones) {
      const roleAlpha = bb.role === "Binder" ? state.binderAlpha : state.targetAlpha;
      if (roleAlpha <= 0.01) continue;
      ctx.save();
      ctx.strokeStyle = bb.role === "Binder" ? "#0284c7" : "#64748b";
      ctx.globalAlpha = bbAlpha * roleAlpha * 0.45;
      ctx.lineWidth = Math.max(2.0, state.camZoom * 0.16);
      ctx.lineJoin = "round";
      ctx.lineCap = "round";
      ctx.beginPath();
      bb.ca_positions.forEach((pos3d, idx) => {
        const rel = vec3Sub(pos3d, frame.origin);
        const loc3d = [vec3Dot(rel, frame.axis_u), vec3Dot(rel, frame.axis_v), vec3Dot(rel, frame.normal)];
        const pt = vec3Lerp(loc3d, [loc3d[0], loc3d[1], 0], state.flattenT);
        const scr = projectLocalPoint(pt, W, H);
        if (idx === 0) ctx.moveTo(scr[0], scr[1]);
        else ctx.lineTo(scr[0], scr[1]);
      });
      ctx.stroke();
      ctx.restore();
    }
  }

  // Precompute current 3D/2D projected positions for all interfacial atoms
  const projectedNodes = map.nodes.map((node, i) => {
    const uv = state.useRelaxedUv ? node.pos_uv : node.pos_uv_raw;
    const loc = computeLocal3D(node.pos_3d, uv, node.role, frame, state.flattenT, state.bookTheta);
    const scr = projectLocalPoint(loc, W, H);
    return { idx: i, node, meta: ds.atom_meta[i], loc, sx: scr[0], sy: scr[1], depth: scr[2] };
  });

  // Identify mating atoms/territories for hover/selection highlighting
  const highlightedAtoms = new Set();
  const highlightedTerritories = new Set();
  if (state.hoveredAtomIdx !== null) {
    highlightedAtoms.add(state.hoveredAtomIdx);
    highlightedTerritories.add(map.nodes[state.hoveredAtomIdx].territory);
  }
  if (state.selectedTerritoryIdx !== null) {
    highlightedTerritories.add(state.selectedTerritoryIdx);
    for (const aIdx of map.territories[state.selectedTerritoryIdx].patch_atoms) {
      highlightedAtoms.add(aIdx);
    }
  }
  for (const c of map.cross_contacts) {
    if (highlightedAtoms.has(c.binder_atom)) {
      highlightedAtoms.add(c.target_atom);
      highlightedTerritories.add(map.nodes[c.target_atom].territory);
    } else if (highlightedAtoms.has(c.target_atom)) {
      highlightedAtoms.add(c.binder_atom);
      highlightedTerritories.add(map.nodes[c.binder_atom].territory);
    }
  }

  // 2. Draw Residue Territory Contours (Target first, then Binder) when flattenT > 0.15
  if (state.showTerritories && state.flattenT > 0.15 && state.useRelaxedUv) {
    const contourBlend = Math.min(1.0, (state.flattenT - 0.15) / 0.55);
    for (const rolePass of ["Target", "Binder"]) {
      const roleAlpha = rolePass === "Binder" ? state.binderAlpha : state.targetAlpha;
      if (roleAlpha <= 0.02) continue;

      for (const terr of map.territories) {
        if (terr.role !== rolePass || terr.contour_uv.length < 3) continue;
        const isHigh = highlightedTerritories.has(terr.idx);
        ctx.save();
        ctx.globalAlpha = contourBlend * roleAlpha;
        ctx.beginPath();
        terr.contour_uv.forEach((uv, idx) => {
          const loc = computeLocal3D(frame.origin, uv, terr.role, frame, 1.0, state.bookTheta);
          // Blend contour elevation with average 3D height of territory atoms when 0 < t < 1
          const scr = projectLocalPoint(loc, W, H);
          if (idx === 0) ctx.moveTo(scr[0], scr[1]);
          else ctx.lineTo(scr[0], scr[1]);
        });
        ctx.closePath();

        if (isHigh) {
          ctx.fillStyle = rolePass === "Binder" ? "rgba(56, 189, 248, 0.22)" : "rgba(148, 163, 184, 0.25)";
        } else {
          ctx.fillStyle = rolePass === "Binder" ? "rgba(15, 23, 42, 0.055)" : "rgba(100, 116, 139, 0.05)";
        }
        ctx.fill();

        if (terr.has_unsatisfied_polar) {
          ctx.strokeStyle = "#d97706";
          ctx.lineWidth = isHigh ? 3.2 : 2.4;
          ctx.setLineDash([6, 4]);
        } else {
          ctx.strokeStyle = rolePass === "Binder"
            ? (isHigh ? "#0284c7" : "#0f172a")
            : (isHigh ? "#334155" : "#64748b");
          ctx.lineWidth = isHigh ? 3.0 : (rolePass === "Binder" ? 2.2 : 1.5);
        }
        ctx.stroke();
        ctx.restore();
      }
    }
  }

  // 3. Draw Intra-Partner First-Shell Edges
  if (state.showIntraEdges) {
    for (const edge of map.intra_edges) {
      const roleAlpha = edge.role === "Binder" ? state.binderAlpha : state.targetAlpha;
      if (roleAlpha <= 0.02) continue;
      const pa = projectedNodes[edge.a];
      const pb = projectedNodes[edge.b];
      ctx.save();
      ctx.globalAlpha = roleAlpha * 0.55;
      if (edge.kind === "IntraHBond") {
        ctx.strokeStyle = "#0891b2";
        ctx.lineWidth = 2.0;
        ctx.setLineDash([4, 3]);
      } else if (edge.kind === "SameResidue") {
        ctx.strokeStyle = edge.role === "Binder" ? "#334155" : "#94a3b8";
        ctx.lineWidth = 1.6;
      } else {
        ctx.strokeStyle = "#cbd5e1";
        ctx.lineWidth = 1.0;
      }
      ctx.beginPath();
      ctx.moveTo(pa.sx, pa.sy);
      ctx.lineTo(pb.sx, pb.sy);
      ctx.stroke();
      ctx.restore();
    }
  }

  // 4. Draw Cross-Interface Contact Lines / Butterfly Arcs
  if (state.showCrossArcs && state.binderAlpha > 0.05 && state.targetAlpha > 0.05) {
    for (const c of map.cross_contacts) {
      const isRelevant = highlightedAtoms.has(c.binder_atom) || highlightedAtoms.has(c.target_atom);
      if (c.kind === "ApolarContact" && !isRelevant) continue;

      const pb = projectedNodes[c.binder_atom];
      const pt = projectedNodes[c.target_atom];
      ctx.save();
      ctx.globalAlpha = isRelevant ? 0.95 : 0.45;
      if (c.kind === "Clash") {
        ctx.strokeStyle = "#f21414";
        ctx.lineWidth = isRelevant ? 2.6 : 1.8;
      } else if (c.kind === "SaltBridge") {
        ctx.strokeStyle = "#9d14ff";
        ctx.lineWidth = isRelevant ? 2.4 : 1.6;
        ctx.setLineDash([5, 3]);
      } else if (c.kind === "HBond") {
        ctx.strokeStyle = "#2563eb";
        ctx.lineWidth = isRelevant ? 2.2 : 1.5;
        ctx.setLineDash([4, 3]);
      } else {
        ctx.strokeStyle = "#64748b";
        ctx.lineWidth = 1.2;
        ctx.setLineDash([2, 3]);
      }

      ctx.beginPath();
      ctx.moveTo(pb.sx, pb.sy);
      if (state.bookTheta > 0.15 && state.flattenT > 0.3) {
        // Curved arc bridging across the Open-Book hinge
        const midX = (pb.sx + pt.sx) * 0.5;
        const span = Math.abs(pb.sx - pt.sx);
        const midY = (pb.sy + pt.sy) * 0.5 - Math.min(90, span * 0.22);
        ctx.quadraticCurveTo(midX, midY, pt.sx, pt.sy);
      } else {
        ctx.lineTo(pt.sx, pt.sy);
      }
      ctx.stroke();
      ctx.restore();
    }
  }

  // 5. Sort Atom Nodes by depth (Target underneath Binder when overlaid at t=1) and draw
  const sortedNodes = [...projectedNodes].sort((a, b) => a.depth - b.depth);
  for (const item of sortedNodes) {
    const { idx, node, meta, sx, sy } = item;
    const roleAlpha = node.role === "Binder" ? state.binderAlpha : state.targetAlpha;
    if (roleAlpha <= 0.02) continue;

    const r = getAtomRadiusPx(node);
    const fill = getAtomFillColor(node, meta);
    const isHigh = highlightedAtoms.has(idx);

    ctx.save();
    ctx.globalAlpha = roleAlpha;

    // Outer warning ring for buried unsatisfied polar atom
    if (node.interaction_summary.is_unsatisfied_buried_polar) {
      ctx.beginPath();
      ctx.arc(sx, sy, r + 3.5, 0, Math.PI * 2);
      ctx.strokeStyle = "#d97706";
      ctx.lineWidth = 2.0;
      ctx.stroke();
    }

    ctx.beginPath();
    ctx.arc(sx, sy, r, 0, Math.PI * 2);

    // Subtle 3D spherical specular highlight when t < 1.0
    if (state.flattenT < 0.95) {
      const grad = ctx.createRadialGradient(sx - r*0.3, sy - r*0.3, r*0.1, sx, sy, r);
      grad.addColorStop(0, "#ffffff");
      grad.addColorStop(0.35, fill);
      grad.addColorStop(1, fill);
      ctx.fillStyle = grad;
    } else {
      ctx.fillStyle = fill;
    }
    ctx.fill();

    ctx.lineWidth = isHigh ? 2.6 : (node.role === "Binder" ? 1.3 : 1.0);
    ctx.strokeStyle = isHigh ? "#facc15" : (node.role === "Binder" ? "#0f172a" : "#475569");
    ctx.stroke();

    // Atom label at high zoom
    if (state.camZoom >= 24 || isHigh) {
      ctx.fillStyle = "#0f172a";
      ctx.font = "600 9px Inter, sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(meta.atom_name, sx, sy - r - 3);
    }
    ctx.restore();
  }

  // 6. Draw Two-Line Residue Labels at Territory Centers when flattenT > 0.35
  if (state.showTerritories && state.flattenT > 0.35 && state.useRelaxedUv) {
    const lblAlpha = Math.min(1.0, (state.flattenT - 0.35) / 0.45);
    for (const terr of map.territories) {
      const roleAlpha = terr.role === "Binder" ? state.binderAlpha : state.targetAlpha;
      if (roleAlpha <= 0.15) continue;
      // Avoid clutter when Target is ghosted directly beneath Binder in Overlay mode
      if (terr.role === "Target" && state.bookTheta < 0.25 && state.binderAlpha > 0.4 && roleAlpha < 0.6) {
        continue;
      }

      const loc = computeLocal3D(frame.origin, terr.label_center_uv, terr.role, frame, 1.0, state.bookTheta);
      const scr = projectLocalPoint(loc, W, H);

      ctx.save();
      ctx.globalAlpha = lblAlpha * roleAlpha;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";

      ctx.font = "700 11px Inter, sans-serif";
      const w1 = ctx.measureText(terr.label_top).width;
      ctx.font = "500 9.5px Inter, sans-serif";
      const w2 = ctx.measureText(terr.label_bottom).width;
      const boxW = Math.max(w1, w2) + 10;
      const boxH = 26;

      ctx.fillStyle = terr.role === "Binder" ? "rgba(255, 255, 255, 0.86)" : "rgba(241, 245, 249, 0.82)";
      ctx.strokeStyle = terr.has_unsatisfied_polar ? "#d97706" : "#cbd5e1";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect(scr[0] - boxW*0.5, scr[1] - boxH*0.5, boxW, boxH, 4);
      ctx.fill();
      ctx.stroke();

      ctx.fillStyle = "#0f172a";
      ctx.font = "700 11px Inter, sans-serif";
      ctx.fillText(terr.label_top, scr[0], scr[1] - 5);

      ctx.fillStyle = "#475569";
      ctx.font = "500 9.5px Inter, sans-serif";
      ctx.fillText(terr.label_bottom, scr[0], scr[1] + 7);
      ctx.restore();
    }
  }

  // 7. Draw Blender-style 3D Orientation Gizmo in top-right corner
  drawOrientationGizmo(W, H);

  ctx.restore();
}

let gizmoHitTargets = [];

function rotateAxisForGizmo(vec) {
  const cy = Math.cos(state.camYaw), sy = Math.sin(state.camYaw);
  const cp = Math.cos(state.camPitch), sp = Math.sin(state.camPitch);
  const x0 = vec[0], y0 = vec[1], z0 = vec[2];
  const x1 = x0 * cy + z0 * sy;
  const z1 = -x0 * sy + z0 * cy;
  const y2 = y0 * cp - z1 * sp;
  const z2 = y0 * sp + z1 * cp;
  return [x1, y2, z2];
}

function drawOrientationGizmo(W, H) {
  const cx = W - 56;
  const cy = 56;
  const armLen = 34;

  // Backdrop disc
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, 44, 0, Math.PI * 2);
  ctx.fillStyle = "rgba(15, 23, 42, 0.78)";
  ctx.fill();
  ctx.strokeStyle = "rgba(148, 163, 184, 0.35)";
  ctx.lineWidth = 1;
  ctx.stroke();

  const axes = [
    { label: "u",  dir: [ 1,  0,  0], color: "#ef4444", pos: true,  yaw: -Math.PI/2, pitch: 0 },
    { label: "-u", dir: [-1,  0,  0], color: "#991b1b", pos: false, yaw:  Math.PI/2, pitch: 0 },
    { label: "v",  dir: [ 0,  1,  0], color: "#22c55e", pos: true,  yaw: 0,          pitch:  Math.PI/2 },
    { label: "-v", dir: [ 0, -1,  0], color: "#166534", pos: false, yaw: 0,          pitch: -Math.PI/2 },
    { label: "n",  dir: [ 0,  0,  1], color: "#3b82f6", pos: true,  yaw: 0,          pitch: 0 },
    { label: "-n", dir: [ 0,  0, -1], color: "#1e40af", pos: false, yaw: Math.PI,    pitch: 0 },
  ];

  const projected = axes.map(a => {
    const r = rotateAxisForGizmo(a.dir);
    return {
      ...a,
      sx: cx + r[0] * armLen,
      sy: cy - r[1] * armLen,
      depth: r[2],
    };
  }).sort((a, b) => a.depth - b.depth);

  gizmoHitTargets = [];

  for (const a of projected) {
    if (a.pos) {
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.lineTo(a.sx, a.sy);
      ctx.strokeStyle = a.color;
      ctx.lineWidth = 2.2;
      ctx.stroke();
    }

    const rad = a.pos ? 8.5 : 6.0;
    ctx.beginPath();
    ctx.arc(a.sx, a.sy, rad, 0, Math.PI * 2);
    ctx.fillStyle = a.color;
    ctx.globalAlpha = a.depth >= -0.1 ? 1.0 : 0.6;
    ctx.fill();
    ctx.strokeStyle = "#0f172a";
    ctx.lineWidth = 1.2;
    ctx.stroke();

    if (a.pos) {
      ctx.fillStyle = "#ffffff";
      ctx.font = "700 9.5px Inter, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(a.label, a.sx, a.sy);
    }

    gizmoHitTargets.push({ sx: a.sx, sy: a.sy, rad: rad + 3, yaw: a.yaw, pitch: a.pitch, label: a.label });
  }
  ctx.restore();
}

function updateInspector() {
  const ds = currentDataset();
  const map = ds.map;
  const container = document.getElementById("inspector-content");

  let terrIdx = state.selectedTerritoryIdx;
  let atomIdx = state.hoveredAtomIdx;
  if (atomIdx !== null) {
    terrIdx = map.nodes[atomIdx].territory;
  }
  if (terrIdx === null) {
    container.innerHTML = `<div style="color:var(--muted);">Hover or click any atom node or residue territory on the map to inspect its 3D/2D metrics and cross-interface contacts.</div>`;
    return;
  }

  const terr = map.territories[terrIdx];
  const terrAtomSet = new Set(terr.patch_atoms);
  const contacts = map.cross_contacts.filter(c =>
    terrAtomSet.has(c.binder_atom) || terrAtomSet.has(c.target_atom)
  );

  let atomDetailHtml = "";
  if (atomIdx !== null) {
    const node = map.nodes[atomIdx];
    const meta = ds.atom_meta[atomIdx];
    atomDetailHtml = `
      <div class="stat-box" style="border-color:var(--accent);">
        <div style="font-weight:700; color:#fff;">Atom ${meta.atom_name} (${meta.element}) — ${terr.label_top} (Chain ${meta.chain_id})</div>
        <div style="margin-top:4px; color:#cbd5e1;">
          ΔSASA: <strong>${node.buried_sasa_a2.toFixed(1)} Å²</strong> (Unbound ${node.free_sasa_a2.toFixed(1)} → Bound ${node.complex_sasa_a2.toFixed(1)} Å²)<br>
          2D Relaxed (u, v): <code>(${node.pos_uv[0].toFixed(2)}, ${node.pos_uv[1].toFixed(2)})</code>
        </div>
      </div>
    `;
  }

  const contactRows = contacts.map(c => {
    const bMeta = ds.atom_meta[c.binder_atom];
    const tMeta = ds.atom_meta[c.target_atom];
    const bTerr = map.territories[map.nodes[c.binder_atom].territory];
    const tTerr = map.territories[map.nodes[c.target_atom].territory];
    const badge = c.kind === "Clash"
      ? `Clash (-${c.overlap_a.toFixed(2)} Å)`
      : `${c.kind} (${c.dist_3d_a.toFixed(2)} Å)`;
    return `
      <div class="contact-item ${c.kind}">
        <span><strong>${bTerr.label_top} ${bMeta.atom_name}</strong> ↔ <strong>${tTerr.label_top} ${tMeta.atom_name}</strong></span>
        <span>${badge}</span>
      </div>
    `;
  }).join("");

  container.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center;">
      <div>
        <div style="font-size:15px; font-weight:700; color:#fff;">${terr.label_top} (${terr.role})</div>
        <div style="font-size:11px; color:var(--muted);">Secondary structure: ${terr.label_bottom} • ${terr.patch_atoms.length} interfacial atoms</div>
      </div>
      <div style="text-align:right;">
        <div style="font-size:14px; font-weight:700; color:var(--accent);">${terr.buried_sasa_a2.toFixed(1)} Å²</div>
        <div style="font-size:10px; color:var(--muted);">Buried ΔSASA</div>
      </div>
    </div>
    ${terr.has_unsatisfied_polar ? `<div style="padding:6px 8px; border-radius:6px; background:rgba(217,119,6,0.18); border:1px solid #d97706; color:#fcd34d; font-size:11px;">⚠️ Contains buried polar atom with 0 satisfied H-bonds or salt bridges.</div>` : ""}
    ${atomDetailHtml}
    <div style="font-size:11px; font-weight:700; color:var(--muted); text-transform:uppercase; margin-top:4px;">
      Cross-Interface Contacts (${contacts.length})
    </div>
    <div class="contact-list">
      ${contactRows || `<div style="color:var(--muted); font-size:11px;">No direct ≤ 4.5 Å cross-contacts (peripheral ΔSASA rim residue).</div>`}
    </div>
  `;
}

function updateStatsPanel() {
  const ds = currentDataset();
  const s = ds.stats;
  document.getElementById("dataset-stats").innerHTML = `
    <div class="stat-box">
      <div class="stat-val">${s.binder_atoms} / ${s.binder_territories}</div>
      <div class="stat-lbl">Binder Atoms / Residues (Chain ${ds.binder_chains.join(",")})</div>
    </div>
    <div class="stat-box">
      <div class="stat-val">${s.target_atoms} / ${s.target_territories}</div>
      <div class="stat-lbl">Target Atoms / Residues (Chain ${ds.target_chains.join(",")})</div>
    </div>
  `;

  const clashes = ds.map.cross_contacts.filter(c => c.kind === "Clash").length;
  const hbonds = ds.map.cross_contacts.filter(c => c.kind === "HBond").length;
  const salts = ds.map.cross_contacts.filter(c => c.kind === "SaltBridge").length;

  document.getElementById("relax-diagnostics").innerHTML = `
    <div class="stat-box">
      <div class="stat-val">${s.edge_rmse_before_a.toFixed(2)} → ${s.edge_rmse_after_a.toFixed(2)} Å</div>
      <div class="stat-lbl">1st-Shell Edge RMSE (Raw → Relaxed)</div>
    </div>
    <div class="stat-box">
      <div class="stat-val">${s.overlaps_before} → ${s.overlaps_after}</div>
      <div class="stat-lbl">2D Hard-Core Overlaps (Raw → Relaxed)</div>
    </div>
    <div class="stat-box">
      <div class="stat-val" style="color:#38bdf8;">${hbonds} HB / ${salts} SB</div>
      <div class="stat-lbl">H-Bonds & Salt Bridges</div>
    </div>
    <div class="stat-box">
      <div class="stat-val" style="color:${clashes > 0 ? '#f87171' : '#4ade80'};">${clashes}</div>
      <div class="stat-lbl">Steric VdW Clashes</div>
    </div>
  `;
}

// Smooth animation loop for t and bookTheta sliders
function stepAnimation() {
  let needsNext = false;
  const dt = state.targetFlattenT - state.flattenT;
  if (Math.abs(dt) > 0.002) {
    state.flattenT += dt * 0.18;
    needsNext = true;
  } else {
    state.flattenT = state.targetFlattenT;
  }

  const db = state.targetBookTheta - state.bookTheta;
  if (Math.abs(db) > 0.002) {
    state.bookTheta += db * 0.18;
    needsNext = true;
  } else {
    state.bookTheta = state.targetBookTheta;
  }

  // Smoothly auto-level camera pitch/yaw when tweening to t=1.0
  if (state.targetFlattenT === 1.0 && needsNext) {
    state.camYaw *= 0.82;
    state.camPitch *= 0.82;
  }

  syncSliderLabels();
  render();
  if (needsNext) {
    requestAnimationFrame(stepAnimation);
  } else {
    state.animating = false;
  }
}

function triggerTween() {
  if (!state.animating) {
    state.animating = true;
    requestAnimationFrame(stepAnimation);
  }
}

function syncSliderLabels() {
  document.getElementById("flatten-slider").value = state.flattenT;
  const modeStr = state.flattenT < 0.05 ? "3D" : (state.flattenT > 0.95 ? "2D Map" : "Bas-Relief");
  document.getElementById("flatten-val").textContent = `${state.flattenT.toFixed(2)} (${modeStr})`;

  document.getElementById("book-slider").value = state.bookTheta;
  const bookStr = state.bookTheta < 0.05 ? "Overlay" : (state.bookTheta > 0.95 ? "Open-Book 180°" : `${Math.round(state.bookTheta*180)}°`);
  document.getElementById("book-val").textContent = `${state.bookTheta.toFixed(2)} (${bookStr})`;
}

