// Custom right-click context menu
const ctxMenu = document.getElementById("context-menu");
function hideContextMenu() {
  ctxMenu.style.display = "none";
}

function showContextMenu(clientX, clientY, atomIdx, terrIdx) {
  const ds = currentDataset();
  const map = ds.map;
  const terr = terrIdx !== null ? map.territories[terrIdx] : null;
  const meta = atomIdx !== null ? ds.atom_meta[atomIdx] : null;

  let headerText = "Viewport Actions";
  if (terr && meta) {
    headerText = `${terr.label_top} (${terr.role}) • Atom ${meta.atom_name}`;
  } else if (terr) {
    headerText = `${terr.label_top} (${terr.role})`;
  }

  let itemsHtml = `<div class="ctx-header">${headerText}</div>`;
  if (terr) {
    itemsHtml += `
      <div class="ctx-item" data-ctx-action="center-territory">🎯 Center Camera on ${terr.label_top}</div>
      <div class="ctx-item" data-ctx-action="select-territory">🔍 Pin ${terr.label_top} in Inspector</div>
      <div class="ctx-sep"></div>
    `;
  }
  itemsHtml += `
    <div class="ctx-item" data-ctx-action="solo-binder">🔵 Solo Mutable Binder Layer</div>
    <div class="ctx-item" data-ctx-action="solo-target">⚪ Solo Immutable Target Layer</div>
    <div class="ctx-item" data-ctx-action="show-both">👁️ Show Both Layers</div>
    <div class="ctx-sep"></div>
    <div class="ctx-item" data-ctx-action="toggle-book">📖 Toggle Overlay ↔ Open-Book (180°)</div>
    <div class="ctx-item" data-ctx-action="reset-camera">🧭 Align Camera to Tangent Plane Π</div>
  `;

  ctxMenu.innerHTML = itemsHtml;
  ctxMenu.style.display = "block";
  const menuW = 230, menuH = 220;
  ctxMenu.style.left = `${Math.min(window.innerWidth - menuW, clientX)}px`;
  ctxMenu.style.top = `${Math.min(window.innerHeight - menuH, clientY)}px`;

  ctxMenu.querySelectorAll("[data-ctx-action]").forEach(item => {
    item.addEventListener("click", (ev) => {
      ev.stopPropagation();
      const act = item.getAttribute("data-ctx-action");
      if (act === "center-territory" && terr) {
        const rect = canvas.getBoundingClientRect();
        const loc = computeLocal3D(map.frame.origin, terr.label_center_uv, terr.role, map.frame, state.flattenT, state.bookTheta);
        const scr = projectLocalPoint(loc, rect.width, rect.height);
        state.camPanX += (rect.width * 0.5 - scr[0]);
        state.camPanY += (rect.height * 0.5 - scr[1]);
        state.selectedTerritoryIdx = terr.idx;
      } else if (act === "select-territory" && terr) {
        state.selectedTerritoryIdx = terr.idx;
        sidebarRight.classList.remove("collapsed");
        toggleRightBtn.textContent = "▶";
      } else if (act === "solo-binder") {
        state.binderAlpha = 1.0;
        state.targetAlpha = 0.05;
        document.getElementById("binder-alpha").value = 1.0;
        document.getElementById("binder-alpha-val").textContent = "1.00";
        document.getElementById("target-alpha").value = 0.05;
        document.getElementById("target-alpha-val").textContent = "0.05";
      } else if (act === "solo-target") {
        state.binderAlpha = 0.05;
        state.targetAlpha = 1.0;
        document.getElementById("binder-alpha").value = 0.05;
        document.getElementById("binder-alpha-val").textContent = "0.05";
        document.getElementById("target-alpha").value = 1.0;
        document.getElementById("target-alpha-val").textContent = "1.00";
      } else if (act === "show-both") {
        state.binderAlpha = 1.0;
        state.targetAlpha = state.bookTheta > 0.5 ? 1.0 : 0.35;
        document.getElementById("binder-alpha").value = state.binderAlpha;
        document.getElementById("binder-alpha-val").textContent = state.binderAlpha.toFixed(2);
        document.getElementById("target-alpha").value = state.targetAlpha;
        document.getElementById("target-alpha-val").textContent = state.targetAlpha.toFixed(2);
      } else if (act === "toggle-book") {
        state.targetBookTheta = state.bookTheta > 0.5 ? 0.0 : 1.0;
        state.targetAlpha = state.targetBookTheta > 0.5 ? 1.0 : 0.35;
        document.getElementById("target-alpha").value = state.targetAlpha;
        document.getElementById("target-alpha-val").textContent = state.targetAlpha.toFixed(2);
        state.camPanX = state.targetBookTheta > 0.5 ? 110 : 0;
        triggerTween();
      } else if (act === "reset-camera") {
        state.camYaw = 0;
        state.camPitch = 0;
        state.camPanX = state.bookTheta > 0.5 ? 110 : 0;
        state.camPanY = 0;
        state.camZoom = 18.0;
      }
      hideContextMenu();
      updateInspector();
      render();
    });
  });
}

canvas.addEventListener("contextmenu", (e) => {
  e.preventDefault();
});

window.addEventListener("click", () => {
  hideContextMenu();
});

// Pointer orbit / pan / zoom / picking on canvas
let isDragging = false;
let dragButton = 0;
let dragStartX = 0, dragStartY = 0;
let dragMoved = false;

canvas.addEventListener("mousedown", (e) => {
  hideContextMenu();
  isDragging = true;
  dragButton = e.button;
  dragMoved = false;
  dragStartX = e.clientX;
  dragStartY = e.clientY;
});

window.addEventListener("mousemove", (e) => {
  if (activeResizer === "left") {
    sidebarLeft.classList.remove("collapsed");
    const newW = Math.max(220, Math.min(560, e.clientX));
    sidebarLeft.style.width = `${newW}px`;
    render();
    return;
  }
  if (activeResizer === "right") {
    sidebarRight.classList.remove("collapsed");
    const newW = Math.max(220, Math.min(560, window.innerWidth - e.clientX));
    sidebarRight.style.width = `${newW}px`;
    render();
    return;
  }

  const rect = canvas.getBoundingClientRect();
  const mx = e.clientX - rect.left;
  const my = e.clientY - rect.top;

  if (isDragging) {
    const dx = e.clientX - dragStartX;
    const dy = e.clientY - dragStartY;
    if (Math.abs(dx) + Math.abs(dy) > 3) dragMoved = true;
    dragStartX = e.clientX;
    dragStartY = e.clientY;

    if (e.shiftKey || dragButton === 2 || state.flattenT > 0.92) {
      state.camPanX += dx;
      state.camPanY += dy;
    } else {
      state.camYaw += dx * 0.008;
      state.camPitch = Math.max(-1.45, Math.min(1.45, state.camPitch + dy * 0.008));
    }
    render();
    return;
  }

  // Hover picking
  if (mx >= 0 && mx <= rect.width && my >= 0 && my <= rect.height) {
    const ds = currentDataset();
    const map = ds.map;
    let bestIdx = null;
    let bestD2 = 196; // 14px radius
    map.nodes.forEach((node, idx) => {
      const roleAlpha = node.role === "Binder" ? state.binderAlpha : state.targetAlpha;
      if (roleAlpha <= 0.05) return;
      const uv = state.useRelaxedUv ? node.pos_uv : node.pos_uv_raw;
      const loc = computeLocal3D(node.pos_3d, uv, node.role, map.frame, state.flattenT, state.bookTheta);
      const scr = projectLocalPoint(loc, rect.width, rect.height);
      const d2 = (scr[0] - mx)*(scr[0] - mx) + (scr[1] - my)*(scr[1] - my);
      if (d2 < bestD2) {
        bestD2 = d2;
        bestIdx = idx;
      }
    });
    if (bestIdx !== state.hoveredAtomIdx) {
      state.hoveredAtomIdx = bestIdx;
      updateInspector();
      render();
    }
  }
});

window.addEventListener("mouseup", (e) => {
  if (activeResizer) {
    activeResizer = null;
    resizerLeft.classList.remove("dragging");
    resizerRight.classList.remove("dragging");
    return;
  }

  if (isDragging && !dragMoved) {
    const rect = canvas.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    // Check if user clicked an axis bubble on the Blender orientation gizmo
    if (dragButton === 0) {
      for (const hit of gizmoHitTargets) {
        const d2 = (mx - hit.sx)*(mx - hit.sx) + (my - hit.sy)*(my - hit.sy);
        if (d2 <= hit.rad * hit.rad) {
          state.camYaw = hit.yaw;
          state.camPitch = hit.pitch;
          isDragging = false;
          render();
          return;
        }
      }
    }

    if (dragButton === 2) {
      // Stationary right-click -> open custom context menu
      const atomIdx = state.hoveredAtomIdx;
      const terrIdx = atomIdx !== null
        ? currentDataset().map.nodes[atomIdx].territory
        : state.selectedTerritoryIdx;
      showContextMenu(e.clientX, e.clientY, atomIdx, terrIdx);
    } else if (dragButton === 0) {
      if (state.hoveredAtomIdx !== null) {
        state.selectedTerritoryIdx = currentDataset().map.nodes[state.hoveredAtomIdx].territory;
      } else {
        state.selectedTerritoryIdx = null;
      }
      updateInspector();
      render();
    }
  }
  isDragging = false;
});

canvas.addEventListener("wheel", (e) => {
  e.preventDefault();
  hideContextMenu();
  const factor = Math.exp(-e.deltaY * 0.0012);
  state.camZoom = Math.max(4.0, Math.min(65.0, state.camZoom * factor));
  render();
}, { passive: false });

window.addEventListener("resize", render);

updateLegend();
updateStatsPanel();
updateInspector();
render();